#include <sys/epoll.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    int epfd = epoll_create1(0);
    struct epoll_event ev, events[10];
    ev.events = EPOLLIN;
    ev.data.fd = 0;
    epoll_ctl(epfd, EPOLL_CTL_ADD, 0, &ev);
    printf("Waiting for input...\n");
    int nfds = epoll_wait(epfd, events, 10, -1);
    printf("Events received: %d\n", nfds);
    close(epfd);
    return 0;
}
